flow.set("queue", allJobs);
flow.set("queueIndex", 0);
node.log("Queue initialised — " + allJobs.length + " meters to read.");
return msg;

const jobs = flow.get("queue");
const i    = flow.get("queueIndex") || 0;

if (!jobs || i >= jobs.length) {
    node.log("✅ All " + (jobs ? jobs.length : 0) + " meters read. Waiting for next cycle.");
    return null;
}

msg.retry = 0;

const job = jobs[i];
flow.set("queueIndex", i + 1);

node.log("[" + (i + 1) + "/" + jobs.length + "] Reading: " + job.name);

// Generate a unique lock ID for this specific dispatch thread
const dId = Date.now();
flow.set("currentDispatchId", dId);
flow.set("activeMeter", job.erp_id);
flow.set("modbusDispatchTime", dId);

msg.job        = job;
msg.dispatchId = dId;
msg.topic      = job.name;
msg.serverId   = job.server;
msg.payload    = {
    fc:       job.fc,
    unitid:   job.unitid,
    address:  job.address,
    quantity: job.quantity
};

return msg;

let currentDispatchId = flow.get('currentDispatchId');
let job = msg.job || {};

if (msg.dispatchId !== currentDispatchId || !currentDispatchId) {
    return null; // Silently drop ghost processes
}

// We got a successful read! DESTROY the lock so no stuttering errors can trigger retries.
flow.set('currentDispatchId', null);
flow.set('modbusDispatchTime', 0);

function getTimestamp() {
    let now = new Date();

    // Subtract 5 seconds to account for network delay and clock drift
    now.setSeconds(now.getSeconds() - 5);

    let yyyy = now.getFullYear();
    let mm   = String(now.getMonth() + 1).padStart(2, '0');
    let dd   = String(now.getDate()).padStart(2, '0');
    let hh   = String(now.getHours()).padStart(2, '0');
    let min  = String(now.getMinutes()).padStart(2, '0');
    let ss   = String(now.getSeconds()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd} ${hh}:${min}:${ss}`;
}

function swapWords16(arr) {
    if (!Array.isArray(arr) || arr.length < 2) return arr;
    let out = [];
    for (let i = 0; i < arr.length; i += 2) {
        if (i + 1 < arr.length) out.push(arr[i + 1], arr[i]);
        else                    out.push(arr[i]);
    }
    return out;
}

function regsToBuffer(regs) {
    const buf = Buffer.alloc(regs.length * 2);
    for (let i = 0; i < regs.length; i++) buf.writeUInt16BE(regs[i] & 0xFFFF, i * 2);
    return buf;
}

function toBigInt64FromRegs(regs, wordOrder) {
    let r = regs.slice();
    if (wordOrder === "LE") r = swapWords16(r);
    let value = 0n;
    for (let i = 0; i < r.length; i++) value = (value << 16n) | BigInt(r[i] & 0xFFFF);
    return value;
}

let regs = [];

if (msg.payload && Array.isArray(msg.payload.data)) {
    regs = msg.payload.data;
} else if (Array.isArray(msg.payload)) {
    regs = msg.payload;
} else {
    node.warn("No register array found in msg.payload.data");
    return null;
}

let dataType  = (job.dataType  || "").toLowerCase();
let wordOrder = job.wordOrder  || "BE";
let scale     = Number(job.scale || 1);
let value     = null;

try {
    if (dataType === "float32") {
        let r = regs.slice(0, 2);
        if (wordOrder === "LE") r = swapWords16(r);
        value = regsToBuffer(r).readFloatBE(0) * scale;
    } else if (dataType === "uint32") {
        let r = regs.slice(0, 2);
        if (wordOrder === "LE") r = swapWords16(r);
        value = regsToBuffer(r).readUInt32BE(0) * scale;
    } else if (dataType === "int32") {
        let r = regs.slice(0, 2);
        if (wordOrder === "LE") r = swapWords16(r);
        value = regsToBuffer(r).readInt32BE(0) * scale;
    } else if (dataType === "uint64") {
        let r = regs.slice(0, 4);
        value = Number(toBigInt64FromRegs(r, wordOrder)) * scale;
    } else if (dataType === "uint16") {
        value = (regs[0] || 0) * scale;
    } else if (dataType === "int16") {
        let v = regs[0] || 0;
        if (v > 32767) v -= 65536;
        value = v * scale;
    } else if (dataType === "float64") {
        let r = regs.slice(0, 4);
        if (wordOrder === "LE") r = r.reverse();
        value = regsToBuffer(r).readDoubleBE(0) * scale;
    } else {
        value = regs;
    }

    msg.payload = {
        sensor_id:     job.erp_id       || null,
        reading_type:  job.reading_type || null,
        reading_time:  getTimestamp(),
        meter_reading: value,
        uom:           job.uom          || null
    };

    node.log('✅ Modbus Read Success! Forwarding erp_id ' + job.erp_id + ' to ERPNext...');
    return msg;

} catch (err) {
    node.error("Conversion failed: " + err.message, msg);
    return null;
}

let job = msg.job || {};

if (msg.statusCode && msg.statusCode >= 400) {
    node.error("❌ ERPNext API Rejected erp_id " + (job.erp_id||'?') + " (Code " + msg.statusCode + "): " + JSON.stringify(msg.payload));
} else if (msg.statusCode) {
    node.log("✅ ERPNext Accepted erp_id " + (job.erp_id||'?'));
} else {
    node.error("❌ HTTP Request failed completely for erp_id " + (job.erp_id||'?'));
}

return msg;

let job = msg.job || {};
let currentDispatchId = flow.get('currentDispatchId');

if (!currentDispatchId) {
    return [null, null];
}

flow.set('currentDispatchId', null);

let retry = msg.retry || 0;

let errMsg = 'unknown error';
try {
    if (msg.error && msg.error.message)                                                      errMsg = msg.error.message;
    else if (msg.payload instanceof Error)                                                   errMsg = msg.payload.message;
    else if (msg.payload && msg.payload.__enc__ && msg.payload.data && msg.payload.data.message) errMsg = msg.payload.data.message;
    else if (msg.payload && msg.payload.data && msg.payload.data.message)                    errMsg = msg.payload.data.message;
    else if (typeof msg.payload === 'string')                                                errMsg = msg.payload;
    else if (msg.payload && msg.payload.message)                                             errMsg = msg.payload.message;
} catch(e){}

if (retry < 2) {
    msg.retry = retry + 1;

    // EXPONENTIAL BACKOFF: 30s then 45s
    const delaySeconds = retry === 1 ? 30 : 45;

    node.warn('⚠️ Retry ' + msg.retry + '/2 — erp_id: ' + (job.erp_id||'?') +
              ' | delay: ' + delaySeconds + 's | reason: ' + errMsg);
    msg.payload = { fc: job.fc, unitid: job.unitid, address: job.address, quantity: job.quantity };

    let newId = Date.now();
    flow.set('currentDispatchId', newId);
    msg.dispatchId = newId;
    flow.set('modbusDispatchTime', newId);

    msg.retryDelaySeconds = delaySeconds;

    return [msg, null];

} else {
    msg.retry = 0;
    node.warn('❌ Final fail, skipping — erp_id: ' + (job.erp_id || '?'));

    // CRITICAL: Clear state before moving to next meter
    flow.set('modbusDispatchTime', 0);
    flow.set('currentDispatchId', null);
    flow.set('activeMeter', null);

    return [null, { payload: "skip" }];
}

const modbusDispatchTime = flow.get('modbusDispatchTime') || 0;

// Only act when a Modbus request is actually in flight
if (modbusDispatchTime <= 0) return null;

const age = Date.now() - modbusDispatchTime;

if (age > 50000) {
    const activeMeter = flow.get('activeMeter');
    const i           = flow.get('queueIndex') || 0;
    const jobs        = flow.get('queue')      || [];
    const stuck       = (i > 0 ? jobs[i - 1] : null) || {};

    node.warn('⏱️ Watchdog: stuck on erp_id ' + activeMeter +
              ' (' + (stuck.name||'?') + ') for ' + Math.round(age/1000) +
              's — force-skipping. queueIndex now ' + i);

    flow.set('modbusDispatchTime', 0);
    flow.set('currentDispatchId', null); // Destroy the lock so late packets bounce
    flow.set('activeMeter', null);

    return { payload: "watchdog_skip" }; 
}
return null;

const job = msg.job || {};
const i = flow.get("queueIndex") || 0;
const jobs = flow.get("queue") || [];

// Log meter completion
node.log("✅ [" + i + "/" + (jobs.length || 0) + "] Complete: " + 
         (job.name || 'unknown'));

// Reset state for next meter
flow.set('currentDispatchId', null);
flow.set('modbusDispatchTime', 0);
flow.set('activeMeter', null);

return msg;
